//#region Typings
export interface TimeframeSelectorBaseProps
  extends FormControlBaseProps,
    StylingProps,
    DataTestId,
    PropsWithChildren {
  /**
   * Shows the "Clear selection" button if set to true.
   * @defaultValue false
   */
  clearable?: boolean;
  /**
   * Determines whether the component is in read-only mode, which means the overlay doesn't open and the onChange isn't called.
   * @defaultValue false
   */
  readOnly?: boolean;
  /** The ISODatetime string of the earliest datetime that can be configured. */
  min?: string;
  /** The ISODatetime string of the latest datetime that can be configured. */
  max?: string;
  /**
   * The precision of the time shown in the display value.
   * @defaultValue 'minutes'
   */
  precision?: 'minutes' | 'seconds' | 'milliseconds';
}

/**
 * Props for the controlled version of the TimeframeSelector.
 */
export interface TimeframeSelectorControlledProps {
  /** The controlled value of the timeframe selector, containing the 'from' and 'to' timeframe details. */
  value:
    | RequireAtLeastOne<{ from: string; to: string }>
    | RequireAtLeastOne<TimeframeV2>
    | null;
  /** Handler gets called if value state has changed. */
  onChange: (value: TimeframeV2 | null) => void;
  /** Setting a default value in controlled mode is not allowed. */
  defaultValue?: never;
}

/**
 * Props for the uncontrolled version of the TimeframeSelector.
 */
export interface TimeframeSelectorUncontrolledProps {
  /** The default, uncontrolled value of the timeframe selector, containing the 'from' and 'to' timeframe details. */
  defaultValue?:
    | RequireAtLeastOne<{ from: string; to: string }>
    | RequireAtLeastOne<TimeframeV2>
    | null;
  /** Handler gets called if value state has changed. */
  onChange?: (value: TimeframeV2 | null) => void;
  /** Setting a value in uncontrolled mode is not allowed. */
  value?: never;
}

/**
 * Props for the controlled and uncontrolled version for the TimeframeSelector component.
 */
export type TimeframeSelectorProps = TimeframeSelectorBaseProps &
  (TimeframeSelectorControlledProps | TimeframeSelectorUncontrolledProps);

type TimeframeSelectorSlotsAndPresetItemsMap = {
  trigger: ReactNode;
  customTrigger: ReactNode;
  presets: ReactNode;
  presetItemsDisplayValuesMap: Map<string, ReactNode | undefined>;
};
//#endregion

const presetItemsDisplayValuesMap = new Map();

/** Iterates over child nodes to extract specific component slots. */
function getItemSlots(children: ReactNode) {
  const slots: TimeframeSelectorSlotsAndPresetItemsMap = {
    trigger: null,
    customTrigger: null,
    presets: null,
    presetItemsDisplayValuesMap,
  };

  for (const child of React.Children.toArray(children)) {
    if (isElement(child) && child.type === Presets) {
      slots.presets = child;
      for (const childItem of React.Children.toArray(child.props.children)) {
        isElement(childItem) &&
          slots.presetItemsDisplayValuesMap.set(
            Object.values(childItem.props.value).join(' '),
            childItem.props.children,
          );
      }
    } else if (_isTimeframeSelectorCustomTriggerElement(child)) {
      slots.customTrigger = child;
    } else if (_isTimeframeSelectorTriggerElement(child)) {
      slots.trigger = child;
    } else {
      // do nothing if the child is null (when rendered conditionally for example) and throw a warning otherwise
      // eslint-disable-next-line no-console
      console.warn('The used child is not supported by the TimeframeSelector.');
    }
  }

  return slots;
}

